contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash, uint256 amount) public payable {
        require(amount >= 1 ether);
        require(address(this).balance >= amount);

        uint256 balBefore = address(c).balance;

        bool reverted;
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;

        // lockInGuess succeeds exactly when the caller sends at least 1 ether,
        // and on success the contract's ether balance grows by exactly the amount sent.
        assert(reverted == (amount < 1 ether) && (reverted || balAfter == balBefore + amount));
    }

    receive() external payable {}
}

