contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(bytes32 guessHash, uint256 lockAmount, uint256 waitBlocks) public payable {
        require(lockAmount == 1 ether, "lock amount must be exactly the required stake");
        require(address(this).balance >= lockAmount, "insufficient balance to lock guess");

        // If waitBlocks is 0, settle should revert because the guess is still active.
        // If waitBlocks is large enough, settle may succeed depending on whether the guess is correct.
        c.lockInGuess{value: lockAmount}(guessHash);

        uint256 contractBalanceBeforeSettle = address(c).balance;

        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint256 contractBalanceAfterSettle = address(c).balance;

        // General rule: settle either reverts (guess still active) or completes after the guess block.
        // When it completes, if the guess was correct the contract pays out exactly the locked amount
        // (contract balance decreases by the payout, here equal to the sole stake); if incorrect, no payout occurs.
        if (waitBlocks == 0) {
            assert(settleReverted);
        } else {
            assert(!settleReverted);
        }

        if (!settleReverted) {
            if (guessHash == blockhash(block.number - 1)) {
                assert(contractBalanceAfterSettle == contractBalanceBeforeSettle - lockAmount);
            } else {
                assert(contractBalanceAfterSettle == contractBalanceBeforeSettle);
            }
        }
    }
}

